import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { releaseNotesMarkup } from '../extension/release-notes.mjs';

const attribute = value => value.replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');

export async function generateReleaseNotes() {
  const html = `<!doctype html>
<!-- Generated by scripts/generate-release-notes.mjs from extension/release-notes.mjs. -->
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>History Sweep · Release notes</title>
<meta name="description" content="What changed in each History Sweep version, with published releases, candidates and development work clearly marked.">
<link rel="canonical" href="https://sweep.agentclub.dev/releases.html">
<link rel="icon" href="assets/mark.svg"><link rel="stylesheet" href="home.css"><link rel="stylesheet" href="releases.css">
</head><body class="release-page">
<header class="nav wrap"><a class="brand" href="./"><img src="assets/product-mark.png" width="34" height="34" alt="">History Sweep</a><nav class="nav-links" aria-label="Main navigation"><a href="./#how" data-zh="使用方式">How it works</a><a href="privacy.html" data-zh="隐私">Privacy</a><a href="https://github.com/agent-club/history-sweep">GitHub</a></nav><div class="nav-actions"><div id="language" class="language-switch" role="group" aria-label="Language"><button type="button" data-language="en" lang="en" aria-label="English" aria-pressed="true">EN</button><button type="button" data-language="zh-CN" lang="zh-CN" aria-label="简体中文" aria-pressed="false">中文</button></div></div></header>
<main class="release-page-main wrap"><a class="release-back" href="./" data-zh="← 返回首页">← Back to home</a><p class="release-eyebrow">HISTORY SWEEP / CHANGELOG</p><h1 data-zh="每一步更新，<br>都有迹可循。">A record of<br>what’s changed.</h1><p class="release-page-intro" data-zh="按版本查看新增与改进。已发布、候选与开发中的内容分别标记。">See additions and improvements by version, with published releases, candidates and work in development marked separately.</p><div class="release-page-content" data-zh="${attribute(releaseNotesMarkup('zh-CN'))}">${releaseNotesMarkup('en')}</div><p class="release-page-footnote" data-zh="开发版本支持离线查看：偏好设置 → 版本与更新；此功能未包含在 v0.5.0 中。">Development builds include offline notes in Preferences → Version &amp; updates; this feature is not in v0.5.0.</p></main><script type="module" src="site.mjs"></script>
</body></html>
`;
  await writeFile(new URL('../site/releases.html', import.meta.url), html);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await generateReleaseNotes();
  console.log('Generated bilingual release notes from the shared extension source.');
}
